        this.total = total;
    }
}

public class FunctionalExample {

    // Pure function:
    // Takes an order and returns a NEW order with discount applied
    static Order applyDiscount(Order order, double percent) {

        // Create and return a new Order object
        return new Order(

            // Formula to calculate discounted total
            order.total * (1 - percent / 100)
        );
    }

    // Pure function to apply tax
    static Order applyTax(Order order) {

        // Return new object instead of modifying existing one
        return new Order(

            // Add 18% tax
            order.total * 1.18
        );
    }

    // Validation function
    static Order validate(Order order) {

        // Validation logic can be added here

        // Return same order after validation
        return order;
    }

    public static void main(String[] args) {

        // Raw order with total = 1000
        Order rawOrder = new Order(1000);

        // Functional pipeline:
        // validate -> applyTax -> applyDiscount
        Order finalOrder =
            applyDiscount(
                applyTax(
                    validate(rawOrder)
                ),
                10 // 10% discount
            );

        // Print final total
        System.out.println(finalOrder.total);
    }
}

