def apply_discount(amount: float, percent: float) -> float:
    return amount * (1 - percent / 100)


def apply_tax(amount: float, percent: float) -> float:
    return amount * (1 + percent / 100)


# Composition: pipe the raw items through a chain of pure functions
def cart_total(items: list, discount_percent: float, tax_percent: float) -> float:
    return apply_tax(apply_discount(subtotal(items), discount_percent), tax_percent)


if __name__ == "__main__":
