import java.util.List;

// Immutable record: just data, no behaviour attached to it
record CartItem(String name, double price, int quantity) {}

class FunctionalCart {

    // Pure function: reads an item, returns a number, changes nothing
    static double itemTotal(CartItem item) {
        return item.price() * item.quantity();
    }

    // Pure function: folds a list of items into one number
    static double subtotal(List<CartItem> items) {
        return items.stream().mapToDouble(FunctionalCart::itemTotal).sum();
    }

    // Pure function: takes an amount, returns a new discounted amount
    static double applyDiscount(double amount, double percent) {
        return amount * (1 - percent / 100);
    }

    // Pure function: takes an amount, returns a new taxed amount
    static double applyTax(double amount, double percent) {
        return amount * (1 + percent / 100);
    }

    // Composition: pipes the cart through a chain of pure functions
    static double cartTotal(List<CartItem> items, double discountPercent, double taxPercent) {
        double sub = subtotal(items);
        double discounted = applyDiscount(sub, discountPercent);
        return applyTax(discounted, taxPercent);
    }
}

public class Main {
    public static void main(String[] args) {
        List<CartItem> cart = List.of(
            new CartItem("Keyboard", 2000, 1),
            new CartItem("Mouse", 500, 2)
        );

        System.out.println(FunctionalCart.cartTotal(cart, 10, 18));
    }
}

