#include <iostream>
#include <vector>
#include <string>

struct CartItem {
    std::string name;
    double price;
    int quantity;
};

// Pure function: reads an item, returns a number, changes nothing
double itemTotal(const CartItem& item) {
    return item.price * item.quantity;
}

// Pure function: folds a list of items into one number
double subtotal(const std::vector<CartItem>& items) {
    double sum = 0;
    for (const auto& item : items) {
        sum += itemTotal(item);
    }
    return sum;
}

// Pure function: takes an amount, returns a new discounted amount
double applyDiscount(double amount, double percent) {
    return amount * (1 - percent / 100);
}

// Pure function: takes an amount, returns a new taxed amount
double applyTax(double amount, double percent) {
    return amount * (1 + percent / 100);
}

// Composition: pipes the cart through a chain of pure functions
double cartTotal(const std::vector<CartItem>& items, double discountPercent, double taxPercent) {
    double sub = subtotal(items);
    double discounted = applyDiscount(sub, discountPercent);
    return applyTax(discounted, taxPercent);
}

int main() {
    std::vector<CartItem> cart = {
        {"Keyboard", 2000, 1},
        {"Mouse", 500, 2}
    };

    std::cout << cartTotal(cart, 10, 18) << std::endl;

    return 0;
}

