class ShoppingCart {
  constructor() {
    this.items = [];
    this.discountPercent = 0;
    this.taxPercent = 0;
  }

  addItem(item) {
    this.items.push(item);
  }

  applyDiscount(percent) {
    this.discountPercent = percent;
  }

  applyTax(percent) {
    this.taxPercent = percent;
  }

  getTotal() {
    const subtotal = this.items.reduce((sum, item) => sum + item.getTotal(), 0);
    const discounted = subtotal * (1 - this.discountPercent / 100);
    return discounted * (1 + this.taxPercent / 100);
  }
}

