import java.util.ArrayList;
import java.util.List;

// Object bundles its data and the methods that operate on it
class CartItem {
    private final String name;
    private final double price;
    private final int quantity;

    CartItem(String name, double price, int quantity) {
        this.name = name;
        this.price = price;
        this.quantity = quantity;
    }

    double getTotal() {
        return price * quantity;
    }
}

class ShoppingCart {
    private final List<CartItem> items = new ArrayList<>();
    private double discountPercent = 0;
    private double taxPercent = 0;

    void addItem(CartItem item) {
        items.add(item);
    }

    void applyDiscount(double percent) {
        this.discountPercent = percent;
    }

    void applyTax(double percent) {
        this.taxPercent = percent;
    }

    double getTotal() {
        double subtotal = 0;
        for (CartItem item : items) {
            subtotal += item.getTotal();
        }
        double discounted = subtotal * (1 - discountPercent / 100);
        return discounted * (1 + taxPercent / 100);
    }
}

public class Main {
    public static void main(String[] args) {
        ShoppingCart cart = new ShoppingCart();
        cart.addItem(new CartItem("Keyboard", 2000, 1));
        cart.addItem(new CartItem("Mouse", 500, 2));
        cart.applyDiscount(10);
        cart.applyTax(18);

        System.out.println(cart.getTotal());
    }
}

